-- A5.12 customer-neutral clean-install reference seed.
-- CLEAN INSTALL ONLY: never apply to an existing customer database.
-- Source allowlist: product navigation metadata and one global SUPERADMIN role.
-- Excluded: users, employees, other roles, customer permission choices, secrets,
-- transactions, balances, inventory, targets, queues, logs, and customer identity.
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS=0;
START TRANSACTION;










SELECT role.id, page.id, 1, 1, 1, 1, 1, CURRENT_TIMESTAMP
FROM auth_role role CROSS JOIN sys_page page
WHERE role.role_code = 'SUPERADMIN' AND role.is_active = 1;

COMMIT;
SET FOREIGN_KEY_CHECKS=1;
